use sqlx::{mysql::MySqlPoolOptions, MySql, Pool};use std::time::Duration;use crate::seed;#[derive(Clone)]pub struct AppState{pub db: Pool<MySql>,}impl AppState{pub async fn new()->anyhow::Result<Self>{let url=std::env::var("DATABASE_URL").expect("DATABASE_URL");let pool=MySqlPoolOptions::new().max_connections(10).acquire_timeout(Duration::from_secs(10)).connect(&url).await?;sqlx::migrate!("./migrations").run(&pool).await?;seed::run(&pool).await?;Ok(Self{db:pool})}}